/* Product walkthrough enhancements: sample data only. */
let selectedClient='All clients',selectedMetric='revenue';
let activity=[];try{const a=JSON.parse(sessionStorage.getItem('srs-ad-activity')||'[]');if(Array.isArray(a))activity=a.filter(x=>typeof x.text==='string'&&typeof x.time==='string').slice(0,30)}catch(e){}
const scoped=()=>campaigns.filter(c=>selectedClient==='All clients'||c.brand===selectedClient);
const total=(list,key)=>list.reduce((n,c)=>n+c[key],0);
function record(text){activity.unshift({text,time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})});activity=activity.slice(0,30);try{sessionStorage.setItem('srs-ad-activity',JSON.stringify(activity))}catch(e){}}
head=function(title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">SRS LOGICS / ADVERTISING WORKSPACE</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${action}</div></div>`};
stats=function(){const a=scoped(),spend=total(a,'spend'),revenue=total(a,'revenue');return `<div class="summary">${[['Total ad spend',money(spend),'Across selected sample accounts','01'],['Attributed revenue',money(revenue),'Platform-reported sample revenue','02'],['Conversions',total(a,'conversions').toLocaleString('en-IN'),'Platform-reported conversion events','03'],['Return on ad spend',spend?(revenue/spend).toFixed(2)+'×':'—','Attributed revenue divided by spend','04']].map(([t,v,n,i])=>`<article class="metric"><div class="metric-top"><span>${t}</span><span class="metric-index">${i}</span></div><div class="value">${v}</div><div class="metric-rule"></div><div class="caption">${n}</div></article>`).join('')}</div>`};
function portfolioControl(){return `<div class="portfolio-bar"><div class="portfolio-select"><span class="scope-icon">▦</span><label for="client-scope">Portfolio</label><select id="client-scope">${['All clients','Northstar Studio','Form & Field','Orbit Software'].map(x=>`<option ${x===selectedClient?'selected':''}>${x}</option>`).join('')}</select></div><div class="period-pill">11–17 Sep 2026 <span>·</span> INR</div><span class="data-mark">Illustrative performance</span></div>`}
chart=function(){let amount=total(scoped(),selectedMetric),weights=[.111,.125,.103,.158,.142,.174,.187],values=weights.map(w=>amount*w),max=Math.max(...values,1)*1.15,pts=values.map((v,i)=>[48+i*93,198-v/max*160]);let path=pts.map(([x,y],i)=>`${i?'L':'M'}${x} ${y}`).join('');return `<div class="panel performance-panel"><div class="panel-head"><div><div class="section-eyebrow">PERFORMANCE</div><h2>Every day, in perspective.</h2></div><div class="chart-switch" aria-label="Chart metric">${[['revenue','Revenue'],['spend','Spend']].map(([k,n])=>`<button data-chart="${k}" aria-pressed="${selectedMetric===k}" class="${selectedMetric===k?'selected':''}">${n}</button>`).join('')}</div></div><div class="chart-total">${money(amount)}<small>Sample ${selectedMetric} · selected portfolio</small></div><div class="chart"><svg viewBox="0 0 650 240" role="img" aria-label="${selectedMetric} across seven sample days"><defs><linearGradient id="premium-area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#306af3" stop-opacity=".2"/><stop offset="1" stop-color="#306af3" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<path d="M48 ${38+i*53.33}H606" stroke="#e9edf4" stroke-dasharray="3 4"/><text x="0" y="${42+i*53.33}" fill="#78869c" font-size="11">${Math.round(max*(1-i/3)/1000)}k</text>`).join('')}<path d="${path}L606 198H48Z" fill="url(#premium-area)"/><path d="${path}" fill="none" stroke="#306af3" stroke-width="3" stroke-linejoin="round"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="#306af3" stroke-width="2"><title>${11+i} September: ${money(values[i])}</title></circle><text x="${x}" y="229" text-anchor="middle" fill="#78869c" font-size="11">${11+i} Sep</text>`).join('')}</svg></div></div>`};
overview=function(){const a=scoped(),spend=total(a,'spend'),review=a.filter(c=>c.status==='In review'),active=a.filter(c=>c.status==='Active');return head('A clearer view. Better decisions.','Your accounts, performance and next actions — together.','<button data-action="export" data-type="portfolio">↓ Export overview</button><button class="primary" data-action="create">＋ New campaign</button>')+portfolioControl()+stats()+`<div class="grid-two">${chart()}<div class="panel channel-panel"><div class="panel-head"><div><div class="section-eyebrow">CHANNEL MIX</div><h2>Where your budget works.</h2></div></div><div class="channel-total"><strong>${money(spend)}</strong><span>Total sample spend</span></div>${['Meta','Google','LinkedIn','TikTok'].map(p=>{let n=total(a.filter(c=>c.platform===p),'spend');return `<div class="split-row">${platform(p)}<div class="split-info"><strong>${p} Ads</strong><div class="progress-track"><span style="width:${spend?n/spend*100:0}%"></span></div></div><div class="split-amount">${money(n)}<small>${spend?(n/spend*100).toFixed(1):'0'}%</small></div></div>`}).join('')}</div></div><div class="action-strip"><div><span class="action-number">${String(review.length).padStart(2,'0')}</span><div><strong>Ready for your review</strong><small>Check creative, targeting and budget.</small></div><button data-action="reviews">Review →</button></div><div><span class="action-number">${String(active.length).padStart(2,'0')}</span><div><strong>Active sample campaigns</strong><small>Manage your portfolio in one place.</small></div><button data-action="go" data-route="campaigns">Manage →</button></div></div><div class="panel"><div class="panel-head"><div><div class="section-eyebrow">CAMPAIGN WORKSPACE</div><h2>What’s running. What’s next.</h2></div><button class="textbtn" data-action="go" data-route="campaigns">View all campaigns →</button></div>${rows(a.slice(0,5))}<div class="panel-bottom"><span>${a.length} campaigns in this portfolio</span><button class="textbtn" data-premium="activity">View activity history →</button></div></div>`};
views.overview=overview;
const originalReports=reportsView;views.reports=()=>originalReports().replace('<div class="summary">',portfolioControl()+'<div class="summary">');
const originalCampaignView=campaignView;views.campaigns=()=>originalCampaignView().replace('<div class="filters">',portfolioControl()+'<div class="filters">');
visibleCampaigns=function(){return scoped().filter(c=>(filter==='All'||c.status===filter)&&(platformFilter==='All'||c.platform===platformFilter)&&`${c.name} ${c.brand} ${c.objective}`.toLowerCase().includes(query.toLowerCase()))};
exportCsv=function(type){const list=type==='filtered'?visibleCampaigns():scoped();let lines;if(type==='accounts')lines=[['Account','Platform','Currency','Network profile','Data type'],...accountKeys().filter(k=>selectedClient==='All clients'||k.split(' / ')[1]===selectedClient).map(k=>[k.split(' / ')[1],k.split(' / ')[0],'INR',profiles[k],'Sample'])];else if(type==='budgets')lines=[['Campaign','Account','Platform','Objective','Daily budget INR','Status'],...list.map(c=>[c.name,c.brand,c.platform,c.objective,c.budget,c.status])];else lines=[['Campaign','Client','Platform','Status','Spend INR','Revenue INR','Conversions','ROAS','Period','Data type'],...list.map(c=>[c.name,c.brand,c.platform,c.status,c.spend,c.revenue,c.conversions,c.spend?(c.revenue/c.spend).toFixed(2):'','11–17 September 2026','Sample'])];const out='\ufeff'+lines.map(r=>r.map(v=>{let t=String(v);if(/^\s*[=+@-]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"'}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([out],{type:'text/csv;charset=utf-8'})),el=document.createElement('a');el.href=url;el.download=`SRS_${type}_Sample.csv`;el.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Selected portfolio report downloaded.')};
let wizard=null;
create=function(asset=0){if(campaigns.length>=100)return toast('Demo campaign limit reached. Reset sample data to continue.');wizard={step:1,name:'',account:asset===1?3:asset===2?2:0,objective:'Sales',budget:1500,asset,region:'India',terms:'',start:'2026-09-18',end:'2026-09-30'};modal('Create a campaign','A guided setup. Every publishing action is simulated.','');drawWizard()};
function drawWizard(){const w=wizard,a=assets[w.asset];$('#dialog .modal-body').innerHTML=`<div class="wizard-progress">${['Campaign','Creative & audience','Review'].map((n,i)=>`<div class="${w.step===i+1?'current':w.step>i+1?'done':''}"><span>${w.step>i+1?'✓':i+1}</span>${n}</div>`).join('')}</div><form id="wizard-form"><div class="form-grid">${w.step===1?`<label class="full">Campaign name<input name="name" maxlength="100" value="${esc(w.name)}" placeholder="e.g. Autumn collection launch" required></label><label>Ad account<select name="account">${accountKeys().map((k,i)=>`<option value="${i}" ${w.account===i?'selected':''}>${esc(k)}</option>`).join('')}</select></label><label>Objective<select name="objective">${['Sales','Traffic','Leads','Awareness'].map(x=>`<option ${w.objective===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Daily budget (INR)<input type="number" name="budget" min="100" max="1000000" step="100" value="${w.budget}" required></label><div class="wizard-budget"><small>Estimated allocation for 7 days</small><strong id="budget-estimate">${money(w.budget*7)}</strong><small>Planning estimate, not a spend commitment</small></div>`:w.step===2?`<label class="full">Creative concept<select name="asset">${assets.map((a,i)=>`<option value="${i}" ${w.asset===i?'selected':''}>${a.title} · ${a.brand}</option>`).join('')}</select></label><label>Location<input name="region" value="${esc(w.region)}" maxlength="100" required></label><label>${accountKeys()[w.account].startsWith('Google')?'Search keywords':'Audience brief'}<input name="terms" value="${esc(w.terms)}" placeholder="${accountKeys()[w.account].startsWith('Google')?'premium essentials, everyday collection':'Design and lifestyle interests'}" maxlength="1000" required></label><label>Start date<input type="date" name="start" value="${w.start}" required></label><label>End date<input type="date" name="end" value="${w.end}" required></label>`:`<div class="campaign-review full"><div class="review-creative asset-art ${a.style}"><span class="art-tag">${a.tag}</span><b>${a.headline}</b><span class="art-bottom">${a.line}</span></div><dl><div><dt>Campaign</dt><dd>${esc(w.name)}</dd></div><div><dt>Account</dt><dd>${esc(accountKeys()[w.account])}</dd></div><div><dt>Daily budget</dt><dd>${money(w.budget)}</dd></div><div><dt>Targeting</dt><dd>${esc(w.region)} · ${esc(w.terms)}</dd></div><div><dt>Schedule</dt><dd>${w.start} → ${w.end}</dd></div><div><dt>Account route</dt><dd>${esc(profiles[accountKeys()[w.account]])}</dd></div></dl></div>`}<div class="inline-note full">${w.step===3?'Save as a draft or send for workspace review. No real ads are submitted and no money is spent.':'Sample configuration. Available objectives and placements depend on the platform in production.'}</div></div><div class="wizard-error" role="alert"></div><div class="modal-actions">${w.step>1?'<button type="button" data-premium="wizard-back">← Back</button>':'<button type="button" data-action="close">Cancel</button>'}${w.step===3?'<button type="submit" name="finish" value="draft">Save draft</button><button type="submit" class="primary" name="finish" value="review">Send for review →</button>':'<button type="submit" class="primary">Continue →</button>'}</div></form>`;$('#wizard-form input, #wizard-form select')?.focus()}
document.addEventListener('submit',e=>{if(e.target.id!=='wizard-form')return;e.preventDefault();const f=e.target,d=new FormData(f),w=wizard;if(w.step===1){w.name=String(d.get('name')).trim();if(!w.name){f.querySelector('.wizard-error').textContent='Enter a campaign name.';return}const nextAccount=Number(d.get('account'));if(nextAccount!==w.account){const brand=accountKeys()[nextAccount].split(' / ')[1];w.asset=Math.max(0,assets.findIndex(a=>a.brand===brand))}w.account=nextAccount;w.objective=d.get('objective');w.budget=Number(d.get('budget'))}if(w.step===2){w.asset=Number(d.get('asset'));w.region=String(d.get('region')).trim();w.terms=String(d.get('terms')).trim();w.start=d.get('start');w.end=d.get('end');if(!w.region||!w.terms||w.end<w.start){f.querySelector('.wizard-error').textContent='Enter targeting details and choose an end date on or after the start date.';return}}if(w.step<3){w.step++;drawWizard();return}const [p,b]=accountKeys()[w.account].split(' / '),status=e.submitter?.value==='review'?'In review':'Draft';campaigns.unshift({id:Math.max(...campaigns.map(c=>c.id),100)+1,name:w.name,brand:b,platform:p,objective:w.objective,status,budget:w.budget,spend:0,revenue:0,conversions:0,asset:w.asset,targeting:{region:w.region,terms:w.terms,negatives:'',start:w.start,end:w.end}});record(`${w.name} · ${status==='Draft'?'draft created':'submitted for review'}`);save();close();selectedClient=b;filter=status;platformFilter='All';query='';go('campaigns');toast(status==='Draft'?'Draft saved.':'Campaign sent for workspace review. No real ads submitted.')});
const originalDetail=detail;detail=function(id){originalDetail(id);const c=campaigns.find(x=>x.id===id);if(!c)return;const a=assets[c.asset];$('#dialog .modal-body').insertAdjacentHTML('afterbegin',`<div class="detail-context"><div class="creative-thumb ${a.style}"><span>${a.tag}</span><b>${a.headline}</b></div><div><div class="section-eyebrow">CAMPAIGN ${c.id}</div><strong>${a.title}</strong><p>${c.targeting?esc(c.targeting.region)+' · '+esc(c.targeting.start)+' to '+esc(c.targeting.end):'Sample campaign configuration'}</p><button class="textbtn" data-premium="duplicate" data-id="${id}">Duplicate as a new draft ↗</button></div></div>`)};
function showActivity(){modal('Workspace activity','Actions taken in this browser tab.',`<div class="activity-list">${activity.length?activity.map(a=>`<div><span class="activity-point"></span><p>${esc(a.text)}<small>${esc(a.time)} · Demo workspace</small></p></div>`).join(''):'<div class="empty"><h3>Your activity will appear here</h3>Create a campaign or update a budget to begin.</div>'}</div><div class="modal-actions"><button data-action="close">Close</button></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-premium]');if(b){if(b.dataset.premium==='wizard-back'){wizard.step--;drawWizard()}if(b.dataset.premium==='activity')showActivity();if(b.dataset.premium==='duplicate'){const c=campaigns.find(c=>c.id===Number(b.dataset.id));close();create(c.asset);wizard.name=c.name+' · Copy';wizard.account=accountKeys().indexOf(c.platform+' / '+c.brand);wizard.budget=c.budget;wizard.objective=c.objective;if(c.targeting)Object.assign(wizard,c.targeting);drawWizard()}}const chartButton=e.target.closest('[data-chart]');if(chartButton){selectedMetric=chartButton.dataset.chart;render()}},false);
document.addEventListener('change',e=>{if(e.target.id==='client-scope'){selectedClient=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.closest('#wizard-form')&&e.target.name==='budget')$('#budget-estimate').textContent=money(Math.max(0,Number(e.target.value))*7)});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const c=campaigns.find(c=>c.id===Number(b.dataset.id));if(b.dataset.action==='clear')selectedClient='All clients';if(b.dataset.action==='status'&&c){const text=c.name;queueMicrotask(()=>record(`${text} · ${c.status.toLowerCase()}`))}if(b.dataset.action==='confirm-reset'){activity=[];selectedClient='All clients';selectedMetric='revenue';try{sessionStorage.removeItem('srs-ad-activity')}catch(e){}}},true);
document.addEventListener('submit',e=>{if(!e.target.checkValidity())return;if(e.target.id==='budget-form'){const c=campaigns.find(c=>c.id===Number(e.target.dataset.id));queueMicrotask(()=>record(`${c.name} · daily budget updated to ${money(c.budget)}`))}if(e.target.id==='route-form'){const key=accountKeys()[Number(e.target.dataset.id)];queueMicrotask(()=>record(`${key} · network assignment updated`))}},true);
const hist=document.createElement('button');hist.className='history-button';hist.textContent='◷ Activity';hist.dataset.premium='activity';$('header').insertBefore(hist,$('.avatar'));
// Prevent hidden navigation from receiving keyboard focus on small screens.
const navMedia=matchMedia('(max-width:850px)');function syncNav(){const open=document.body.classList.contains('menu-open');$('aside').inert=navMedia.matches&&!open;$('.mobile-toggle').setAttribute('aria-expanded',String(open))}new MutationObserver(syncNav).observe(document.body,{attributes:true,attributeFilter:['class']});navMedia.addEventListener('change',syncNav);syncNav();
document.addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('aside, .mobile-toggle'))document.body.classList.remove('menu-open')});
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus()});
window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()});
render();
